fn native_aio_wait_routes_another_requests_completion() {
    use std::{process::Command, time::Duration};

    let scratch = support::Scratch::new("aio-owned-completion-routing");
    let input = scratch.path().join("routing.lim");
    let binary = scratch.path().join("routing");
    let library = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("library");
    let source = format!(
        r#"#alias AioOwnedCompleted = "{0}/aio_owned.lim::AioOwnedCompleted"
#alias AioOwnedContext = "{0}/aio_owned.lim::AioOwnedContext"
#alias AioOwnedContextCreate = "{0}/aio_owned.lim::AioOwnedContextCreate"
#alias AioOwnedPending = "{0}/aio_owned.lim::AioOwnedPending"
#alias AioOwnedSubmit = "{0}/aio_owned.lim::AioOwnedSubmit"
#alias AioOwnedWait = "{0}/aio_owned.lim::AioOwnedWait"
#alias LinuxTimespec = "{0}/linux_x86_64.lim::LinuxTimespec"
#alias aio-owned-completed-destroy = "{0}/aio_owned.lim::aio-owned-completed-destroy"
#alias aio-owned-completed-result = "{0}/aio_owned.lim::aio-owned-completed-result"
#alias aio-owned-context-create = "{0}/aio_owned.lim::aio-owned-context-create"
#alias aio-owned-context-destroy = "{0}/aio_owned.lim::aio-owned-context-destroy"
#alias aio-owned-poll-submit = "{0}/aio_owned.lim::aio-owned-poll-submit"
#alias aio-owned-wait = "{0}/aio_owned.lim::aio-owned-wait"
#alias linux-close = "{0}/linux_x86_64.lim::linux-close"
#alias linux-eventfd2 = "{0}/linux_x86_64.lim::linux-eventfd2"
#alias linux-mmap = "{0}/linux_x86_64.lim::linux-mmap"
#alias linux-munmap = "{0}/linux_x86_64.lim::linux-munmap"
#alias linux-nanosleep = "{0}/linux_x86_64.lim::linux-nanosleep"
#alias linux-write = "{0}/linux_x86_64.lim::linux-write"
#fn main {{
  #params = ();
  #returns = #u64;
  #effects = (#global-access #io (#effects-of aio-owned-completed-destroy) (#effects-of aio-owned-context-create) (#effects-of aio-owned-context-destroy) (#effects-of aio-owned-poll-submit) (#effects-of aio-owned-wait) (#effects-of linux-close) (#effects-of linux-eventfd2) (#effects-of linux-mmap) (#effects-of linux-munmap) (#effects-of linux-nanosleep) (#effects-of linux-write)); #body = (
               (#let context-result AioOwnedContextCreate
                 (#call aio-owned-context-create ()))
               (#let-mut context AioOwnedContext
                 (#match context-result
                   (#case (AioOwnedContextCreate.AioOwnedContextCreated owner) owner)
                   (#case (AioOwnedContextCreate.AioOwnedContextCreateFailed error)
                     (#block (#forget error) (#unreachable)))))
               (#let fd-b #i64 (#call linux-eventfd2 ((initial-value 0u32) (flags 0i32))))
               (#let fd-a #i64 (#call linux-eventfd2 ((initial-value 0u32) (flags 0i32))))
               (#assert (#i64::ge fd-a 0i64))
               (#assert (#i64::ge fd-b 0i64))
               (#let submission-b AioOwnedSubmit
                 (#call aio-owned-poll-submit
                   ((context (#borrow context)) (fd fd-b) (events 1u16))))
               (#let pending-b AioOwnedPending
                 (#match submission-b
                   (#case (AioOwnedSubmit.AioOwnedSubmitted operation) operation)
                   (#case (AioOwnedSubmit.AioOwnedSubmitFailed error)
                     (#block (#forget error) (#unreachable)))))
               (#let submission-a AioOwnedSubmit
                 (#call aio-owned-poll-submit
                   ((context (#borrow context)) (fd fd-a) (events 1u16))))
               (#let pending-a AioOwnedPending
                 (#match submission-a
                   (#case (AioOwnedSubmit.AioOwnedSubmitted operation) operation)
                   (#case (AioOwnedSubmit.AioOwnedSubmitFailed error)
                     (#block (#forget error) (#unreachable)))))
               (#let scratch (#ptr-mut #u8)
                 (#unsafe (#unsafe-call linux-mmap
                   ((address (#ptr-null (#ptr-mut #u8))) (length 4096usize)
                    (protection 3u32) (flags 34u32) (fd -1i64) (offset 0i64)))))
               (#let value (#ptr-mut #u64)
                 (#unsafe (#asm (#ptr-mut #u64) ((rdi scratch)) "lea rax, [rdi+256]")))
               (#unsafe (#ptr-write value 1u64))
               (#let bytes (#ptr-mut #u8)
                 (#unsafe (#asm (#ptr-mut #u8) ((rdi scratch)) "lea rax, [rdi+256]")))
               (#assert (#i64::eq
                 (#unsafe (#unsafe-call linux-write ((fd fd-b) (source bytes) (count 8usize))))
                 8i64))
               (#let delay LinuxTimespec
                 (#struct-literal LinuxTimespec ((seconds 0i64) (nanoseconds 10000000i64))))
               (#let-mut remaining LinuxTimespec
                 (#struct-literal LinuxTimespec ((seconds 0i64) (nanoseconds 0i64))))
               (#assert (#i64::eq (#call linux-nanosleep
                 ((request (#borrow delay)) (remaining (#borrow-mut remaining)))) 0i64))
               (#assert (#i64::eq
                 (#unsafe (#unsafe-call linux-write ((fd fd-a) (source bytes) (count 8usize))))
                 8i64))
               (#let wait-a AioOwnedWait (#call aio-owned-wait ((operation pending-a))))
               (#let completed-a AioOwnedCompleted
                 (#match wait-a
                   (#case (AioOwnedWait.AioOwnedFinished operation) operation)
                   (#case (AioOwnedWait.AioOwnedWaitFailed failure)
                     (#block
                       (#let (#tuple still-pending error)
                         (#tuple AioOwnedPending #i64) failure)
                       (#forget still-pending)
                       (#forget error)
                       (#unreachable)))))
               (#let wait-b AioOwnedWait (#call aio-owned-wait ((operation pending-b))))
               (#let completed-b AioOwnedCompleted
                 (#match wait-b
                   (#case (AioOwnedWait.AioOwnedFinished operation) operation)
                   (#case (AioOwnedWait.AioOwnedWaitFailed failure)
                     (#block
                       (#let (#tuple still-pending error)
                         (#tuple AioOwnedPending #i64) failure)
                       (#forget still-pending)
                       (#forget error)
                       (#unreachable)))))
               (#assert (#i64::eq (#call aio-owned-completed-result
                 ((operation (#borrow completed-a)))) 1i64))
               (#assert (#i64::eq (#call aio-owned-completed-result
                 ((operation (#borrow completed-b)))) 1i64))
               (#assert (#i64::eq (#call aio-owned-completed-destroy
                 ((operation completed-a))) 0i64))
               (#assert (#i64::eq (#call aio-owned-completed-destroy
                 ((operation completed-b))) 0i64))
               (#assert (#i64::eq (#call aio-owned-context-destroy
                 ((context context))) 0i64))
               (#assert (#i64::eq (#call linux-close ((fd fd-a))) 0i64))
               (#assert (#i64::eq (#call linux-close ((fd fd-b))) 0i64))
               (#assert (#i64::eq (#unsafe (#unsafe-call linux-munmap
                 ((address scratch) (length 4096usize)))) 0i64))
               (#return 42u64)
  );
}}
"#,
        library.display()
    );
    std::fs::write(&input, source).unwrap();
    let compilation = Command::new(env!("CARGO_BIN_EXE_lim"))
        .arg(&input)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("compile completion-routing test");
    assert!(
        compilation.status.success(),
        "{}",
        String::from_utf8_lossy(&compilation.stderr)
    );
    let (status, _, stderr) = support::run(&mut Command::new(binary), Duration::from_secs(5), 1024)
        .expect("run completion-routing test");
    assert_eq!(status.code(), Some(42), "{stderr:?}");
}
